/* ==========================================================================
   Sydney Leak Experts | Contact page body
   Scoped under .sle-contact. Style block sits inside the wrapper so Base44
   files the markup and its CSS into the same scoped part.
   Header and footer omitted: the Base44 site uses globals for those.
   ========================================================================== */

.sle-contact{
  --navy:#0E2A43;
  --navy2:#0A2033;
  --orange:#F26A21;
  --orange2:#ff8336;
  --ink:#122a3f;
  --body:#4b5b69;
  --mut:#8295a4;
  --line:#e6edf3;
  --bg:#eef3f9;
  --bg2:#e7eef7;
  --head:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;
  --sans:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;

  background:var(--bg);
  color:var(--body);
  font-family:var(--sans);
  font-size:16px;
  line-height:1.6;
  overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}

.sle-contact *,
.sle-contact *::before,
.sle-contact *::after{box-sizing:border-box}

.sle-contact h1,
.sle-contact h2,
.sle-contact h3{
  font-family:var(--head);
  color:var(--navy);
  line-height:1.2;
  margin:0;
}
.sle-contact p{margin:0 0 12px}
.sle-contact a{color:inherit;text-decoration:none}
.sle-contact img{max-width:100%;display:block}
.sle-contact input,
.sle-contact select,
.sle-contact textarea{min-width:0}

.sle-contact .wrap{max-width:1220px;margin:0 auto;padding:0 22px}
.sle-contact section{padding:72px 0}

.sle-contact .k{
  display:inline-block;
  font-family:var(--head);
  font-weight:600;
  color:var(--orange);
  font-size:.78rem;
  text-transform:uppercase;
  letter-spacing:1.4px;
}

.sle-contact .eyebrow{
  display:inline-flex;
  align-items:center;
  gap:9px;
  background:#fff;
  border:1px solid var(--line);
  color:var(--navy);
  font-family:var(--head);
  font-weight:600;
  font-size:.82rem;
  padding:7px 15px;
  border-radius:999px;
  box-shadow:0 6px 18px -12px rgba(14,42,67,.4);
}
.sle-contact .eyebrow::before{
  content:"";
  width:9px;
  height:9px;
  border-radius:50%;
  background:var(--orange);
}

.sle-contact .sec-head{text-align:center;max-width:720px;margin:0 auto 38px}
.sle-contact .sec-head h2{font-size:clamp(2rem,4vw,3rem);margin:14px 0 10px}

/* --- Buttons --- */
.sle-contact .btn{
  display:inline-flex;
  align-items:center;
  gap:9px;
  font-family:var(--head);
  font-weight:600;
  font-size:1rem;
  padding:15px 26px;
  border-radius:999px;
  cursor:pointer;
  border:2px solid transparent;
  transition:.15s;
}
.sle-contact .btn svg{width:17px;height:17px;flex:none}
.sle-contact .btn-o{background:var(--orange);color:#fff}
.sle-contact .btn-o:hover{background:var(--orange2)}

/* --- Page hero --- */
.sle-contact .ph{
  background:var(--navy);
  color:#fff;
  position:relative;
  overflow:hidden;
  padding:60px 0 58px;
}
.sle-contact .ph::after{
  content:"";
  position:absolute;
  inset:0;
  background-image:radial-gradient(rgba(255,255,255,.045) 1.3px,transparent 1.3px);
  background-size:24px 24px;
  pointer-events:none;
}
.sle-contact .ph .wrap{position:relative;z-index:2;max-width:880px}
.sle-contact .ph .crumb{color:#9fb8cb;font-size:.84rem;margin-bottom:16px}
.sle-contact .ph .crumb a:hover{color:#fff}
.sle-contact .ph .crumb b{color:var(--orange2);font-weight:500}
.sle-contact .ph .eyebrow{
  background:rgba(242,106,33,.16);
  border-color:transparent;
  color:var(--orange2);
  box-shadow:none;
}
.sle-contact .ph h1{color:#fff;font-size:clamp(2.2rem,4.8vw,3.5rem);margin:14px 0}
.sle-contact .ph p{color:#bcd0df;font-size:1.14rem;max-width:62ch;margin:0}

/* --- Contact grid --- */
.sle-contact .ct-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:40px;
  align-items:start;
}
.sle-contact .ct-grid > *{min-width:0}
.sle-contact .ct-h2{font-size:clamp(1.8rem,3.4vw,2.4rem);margin:12px 0 18px}

.sle-contact .ct-cards{display:flex;flex-direction:column;gap:14px}
.sle-contact .ct-card{
  display:flex;
  gap:16px;
  background:#fff;
  border:1px solid var(--line);
  border-radius:16px;
  padding:22px;
}
.sle-contact .ct-card > div{min-width:0}
.sle-contact .ct-card .ct-ic{
  flex:none;
  width:50px;
  height:50px;
  border-radius:13px;
  background:var(--bg);
  color:var(--orange);
  display:grid;
  place-items:center;
}
.sle-contact .ct-card svg{width:24px;height:24px}
.sle-contact .ct-card h3{font-size:1.08rem;margin-bottom:3px}
.sle-contact .ct-card p{margin:0;font-size:.94rem;overflow-wrap:anywhere}
.sle-contact .ct-card a{color:var(--navy);font-weight:600;overflow-wrap:anywhere}
.sle-contact .ct-card a:hover{color:var(--orange)}

.sle-contact .ct-map{
  border-radius:16px;
  overflow:hidden;
  background:var(--bg2);
  margin-top:14px;
}
.sle-contact .ct-map img{width:100%;height:280px;object-fit:cover}

.sle-contact .hours{list-style:none;margin:6px 0 0;padding:0}
.sle-contact .hours li{
  display:flex;
  justify-content:space-between;
  gap:12px;
  padding:7px 0;
  border-bottom:1px solid var(--line);
  font-size:.94rem;
}
.sle-contact .hours li:last-child{border-bottom:none}
.sle-contact .hours b{color:var(--navy);font-family:var(--head)}

/* --- Enquiry form --- */
.sle-contact .book-card{background:#fff;border-radius:20px;padding:30px}
.sle-contact .book-card h3{
  font-size:1.35rem;
  color:var(--navy);
  text-transform:none;
  letter-spacing:normal;
  margin-bottom:6px;
}
.sle-contact .book-card .bc-sub{font-size:.92rem;margin:0 0 16px}
.sle-contact .brow{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.sle-contact .bfield{margin-bottom:14px}
.sle-contact .bfield label{
  display:block;
  font-size:.78rem;
  font-weight:600;
  color:var(--navy);
  margin-bottom:6px;
  font-family:var(--head);
}
.sle-contact .bfield .rq{color:var(--orange)}
.sle-contact .bfield input,
.sle-contact .bfield select,
.sle-contact .bfield textarea{
  width:100%;
  background:var(--bg);
  border:1px solid var(--line);
  border-radius:10px;
  padding:12px 13px;
  font-family:var(--sans);
  font-size:.94rem;
  color:var(--navy);
}
.sle-contact .bfield textarea{min-height:90px;resize:vertical}

/* --- FAQs --- */
.sle-contact .faq-sec{background:#fff}
.sle-contact .faq-wrap{max-width:860px;margin:0 auto}
.sle-contact .fq{
  border:1px solid var(--line);
  border-radius:13px;
  margin:12px 0;
  overflow:hidden;
  background:#fff;
}
.sle-contact .fq summary{
  list-style:none;
  cursor:pointer;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:14px;
  padding:18px 22px;
  font-family:var(--head);
  font-weight:600;
  color:var(--navy);
  font-size:1.08rem;
}
.sle-contact .fq summary::-webkit-details-marker{display:none}
.sle-contact .fq .cv{color:var(--orange);transition:.2s}
.sle-contact .fq .cv svg{width:18px;height:18px;transform:rotate(90deg)}
.sle-contact .fq[open] .cv svg{transform:rotate(-90deg)}
.sle-contact .fa{padding:0 22px 20px;color:var(--body)}

/* --- Responsive --- */
@media (max-width:900px){
  .sle-contact section{padding:54px 0}
  .sle-contact .ct-grid{grid-template-columns:minmax(0,1fr)}
  .sle-contact .ph{padding:38px 0}
}

@media (max-width:640px){
  .sle-contact section{padding:44px 0}
  .sle-contact .brow{grid-template-columns:1fr}
  .sle-contact .sec-head{margin-bottom:28px}
  .sle-contact .sec-head h2{font-size:1.7rem}
  .sle-contact .ph h1{font-size:2rem}
  .sle-contact .ph p{font-size:1.04rem}
  .sle-contact .btn{padding:14px 20px}
  .sle-contact .book-card{padding:22px}
}
